import React from 'react';
import axios from 'axios';

const ProSeasonQuery = ({ apiKey }) => {
  const [stock, setStock] = useState('');
  const [bestTime, setBestTime] = useState(null);

  useEffect(() => {
    async function fetchStockData(stock) {
      try {
        const response = await axios.get(`https://api.proseason.io/v2/stocks/${stock}?apiKey=${apiKey}`);
        setStock(response.data.stock);
        setBestTime(response.data.bestTime);
      } catch (error) {
        console.error('Error fetching stock data:', error);
      }
    }

    fetchStockData(stock);
  }, [stock, apiKey]);

  return (
    <div>
      <input type="text" value={stock} onChange={(e) => setStock(e.target.value)} />
      {bestTime && (
        <p>Best Time to Buy: {bestTime}</p>
      )}
      <button onClick={() => setBestTime(null)}>Reset</button>
    </div>
  );
};

export default ProSeasonQuery;
```

